#!/usr/bin/env python3
"""Render maintained Markdown views from machine-readable repository data."""
from __future__ import annotations
import argparse
import json
import os
from collections import Counter
from pathlib import Path
from typing import Any
ROOT = Path(__file__).resolve().parents[1]

def load_json(path: str) -> dict[str, Any]:
    return json.loads((ROOT / path).read_text(encoding='utf-8'))

def cell(value: Any) -> str:
    if value is None or value == '':
        return '—'
    text = str(value).replace('\n', ' ').replace('|', '\\|')
    return ' '.join(text.split())

def code(value: str) -> str:
    return f'`{value}`'

def relative_link(output_path: str, target: str, label: str | None=None) -> str:
    start = (ROOT / output_path).parent
    rel = os.path.relpath(ROOT / target, start=start).replace(os.sep, '/')
    return f'[{label or Path(target).name}]({rel})'

def review_cell(item: dict[str, Any], output_path: str) -> str:
    review = item.get('review')
    if not review:
        return '—'
    record = relative_link(output_path, review['review_record'], review['disposition'])
    revision = code(review['reviewed_revision'][:12])
    return f'{record} at {revision}'

def render_claim_ledger(claims: dict[str, Any]) -> str:
    items = claims['claims']
    counts = Counter((item['status'] for item in items))
    lines = ['# Claim Ledger', '', '> Generated from [`claim_ledger.json`](claim_ledger.json). Do not edit this file by hand.', '> Merge location, CI, and provenance do not determine mathematical authority; explicit claim status and bound review records do.', '', '## Status summary', '', '| Status | Count |', '|---|---:|']
    for status in claims['status_vocabulary']:
        lines.append(f'| {code(status)} | {counts.get(status, 0)} |')
    lines += ['', '## Claims', '', '| ID | Status | Track | Statement | Dependencies | Review | Note |', '|---|---|---|---|---|---|---|']
    for item in items:
        dependencies = ', '.join((code(dep) for dep in item.get('depends_on', []))) or '—'
        lines.append('| ' + ' | '.join([code(item['id']), code(item['status']), code(item['track']), cell(item['statement']), dependencies, review_cell(item, 'research/CLAIM_LEDGER.md'), cell(item.get('note', ''))]) + ' |')
    lines += ['', 'The canonical vocabulary and synchronization rules are defined in [`governance/CLAIM-STATUS.md`](../governance/CLAIM-STATUS.md) and [`governance/REVIEW-AND-FREEZE.md`](../governance/REVIEW-AND-FREEZE.md).', '']
    return '\n'.join(lines)

def render_proof_graph(graph: dict[str, Any]) -> str:
    nodes = graph['nodes']
    edges = graph['edges']
    type_counts = Counter((node['type'] for node in nodes))
    status_counts = Counter((node['status'] for node in nodes))
    lines = ['# Proof Graph', '', '> Generated from [`proof_graph.json`](proof_graph.json). Do not edit this file by hand.', '> Graph structure records dependency and disposition; it is not a substitute for mathematical review.', '', '## Summary', '', f'- Nodes: **{len(nodes)}**', f'- Directed edges: **{len(edges)}**', f"- Open leaf nodes: **{sum((1 for node in nodes if node['type'] == 'leaf' and node['status'] == 'open'))}**", '- Node types: ' + ', '.join((f'{code(k)} {v}' for k, v in sorted(type_counts.items()))), '- Node statuses: ' + ', '.join((f'{code(k)} {v}' for k, v in sorted(status_counts.items()))), '', '## Nodes', '', '| ID | Title | Type | Status | Artifact | Review / note |', '|---|---|---|---|---|---|']
    for node in nodes:
        artifact = node.get('artifact')
        artifact_cell = relative_link('research/PROOF_GRAPH.md', f'research/{artifact}', artifact) if artifact else '—'
        review = node.get('review_artifact')
        review_note = relative_link('research/PROOF_GRAPH.md', review, 'review') if review else cell(node.get('note', ''))
        if review and node.get('note'):
            review_note += '; ' + cell(node['note'])
        lines.append('| ' + ' | '.join([code(node['id']), cell(node['title']), code(node['type']), code(node['status']), artifact_cell, review_note]) + ' |')
    lines += ['', '## Edges', '', '| From | Relation | To |', '|---|---|---|']
    for edge in edges:
        lines.append(f"| {code(edge['from'])} | {code(edge['kind'])} | {code(edge['to'])} |")
    lines.append('')
    return '\n'.join(lines)

def render_work_queue(queue: dict[str, Any]) -> str:
    lines = ['# Work Queue', '', '> Generated from [`work_queue.json`](work_queue.json). Do not edit this file by hand.', '> Only open leaves appear in the active queue. Reviewed or disposed leaves are retained below as explicit dispositions.', '', '## Active leaves', '', '| Priority | Leaf | Graph node | Issue | Claim dependencies | Track |', '|---|---|---|---|---|---|']
    for leaf in queue['leaves']:
        leaf_link = relative_link('research/WORK_QUEUE.md', leaf['artifact'], leaf['title'])
        issue = f"[#{leaf['issue_number']}](https://github.com/snissn/planar-jacobian/issues/{leaf['issue_number']})"
        deps = ', '.join((code(dep) for dep in leaf['claim_dependencies'])) or '—'
        track = relative_link('research/WORK_QUEUE.md', leaf['track_artifact'], Path(leaf['track_artifact']).name)
        lines.append(f"| {code(leaf['priority'])} | {leaf_link} | {code(leaf['graph_node'])} | {issue} | {deps} | {track} |")
    lines += ['', '## Recorded dispositions', '', '| Leaf | Status | Disposition | Issue | Review / successor | Note |', '|---|---|---|---|---|---|']
    for item in queue.get('dispositions', []):
        leaf_link = relative_link('research/WORK_QUEUE.md', item['artifact'], item['title'])
        issue = f"[#{item['issue_number']}](https://github.com/snissn/planar-jacobian/issues/{item['issue_number']})"
        pointer = '—'
        if item.get('review_artifact'):
            pointer = relative_link('research/WORK_QUEUE.md', item['review_artifact'], 'review')
        elif item.get('successor_graph_node'):
            pointer = code(item['successor_graph_node'])
        lines.append(f"| {leaf_link} | {code(item['status'])} | {code(item['disposition'])} | {issue} | {pointer} | {cell(item.get('note', ''))} |")
    lines.append('')
    return '\n'.join(lines)

def render_issue_index(queue: dict[str, Any]) -> str:
    lines = ['# GitHub Issue Index', '', '> Generated from [`work_queue.json`](work_queue.json). Do not edit this file by hand.', '', 'Issue [#2](https://github.com/snissn/planar-jacobian/issues/2) is the durable coordination surface. Leaf packets carry the scientific task contract; GitHub issues mirror coordination state.', '', '## Active leaves', '', '| Leaf | Graph node | Issue |', '|---|---|---|']
    for leaf in sorted(queue['leaves'], key=lambda item: item['id']):
        artifact = relative_link('research/ISSUE_INDEX.md', leaf['artifact'], Path(leaf['artifact']).name)
        issue = f"[#{leaf['issue_number']}](https://github.com/snissn/planar-jacobian/issues/{leaf['issue_number']})"
        lines.append(f"| {artifact} | {code(leaf['graph_node'])} | {issue} |")
    lines += ['', '## Disposed or reviewed leaves', '', '| Leaf | Status | Issue |', '|---|---|---|']
    for item in sorted(queue.get('dispositions', []), key=lambda row: row['id']):
        artifact = relative_link('research/ISSUE_INDEX.md', item['artifact'], Path(item['artifact']).name)
        issue = f"[#{item['issue_number']}](https://github.com/snissn/planar-jacobian/issues/{item['issue_number']})"
        lines.append(f"| {artifact} | {code(item['status'])} | {issue} |")
    lines.append('')
    return '\n'.join(lines)

def render_legacy_migration(legacy: dict[str, Any]) -> str:
    lines = ['# Legacy Claim-Ledger Migration', '', '> Generated from [`legacy_claim_ledger.json`](legacy_claim_ledger.json). Do not edit this file by hand.', '> This is a historical reconciliation record, not a second authoritative claim ledger.', '', f"Source: {code(legacy['source_ref'])}, path {code(legacy['source_path'])}.", '', '## Status migration', '', '| Legacy status | Canonical treatment | Migration rule |', '|---|---|---|']
    for row in legacy['status_migration']:
        lines.append(f"| {code(row['legacy_status'])} | {cell(row['canonical_treatment'])} | {cell(row['rule'])} |")
    lines += ['', '## Preserved legacy claims', '', '| Legacy ID | Legacy status | Statement | Canonical links | Original note |', '|---|---|---|---|---|']
    for item in legacy['claims']:
        links = ', '.join((f"{code(link['claim_id'])} ({cell(link['relation'])})" for link in item.get('canonical_links', []))) or 'unmapped; retained here only'
        lines.append('| ' + ' | '.join([code(item['id']), code(item['legacy_status']), cell(item['statement']), links, cell(item.get('notes', ''))]) + ' |')
    lines += ['', 'No migration row promotes a scientific claim. Canonical statements and statuses remain those in [`claim_ledger.json`](claim_ledger.json).', '']
    return '\n'.join(lines)

def render_status(claims: dict[str, Any], graph: dict[str, Any], queue: dict[str, Any], manifest: dict[str, Any]) -> str:
    claim_counts = Counter((item['status'] for item in claims['claims']))
    node_counts = Counter((item['status'] for item in graph['nodes']))
    metadata_exports = [item for item in manifest['exports'] if item.get('storage_mode') == 'metadata_only']
    p0 = [item for item in queue['leaves'] if item['priority'] == 'P0']
    lines = ['# Repository Status', '', '> Generated from maintained JSON ledgers by [`scripts/render_views.py`](scripts/render_views.py).', '', '## Authority and scientific boundary', '', '- **Canonical integration surface:** latest `main`; branches are short-lived transport surfaces.', '- **Main theorem:** open; `ROOT-JC2` remains `blocked`.', '- **Merge meaning:** preservation and transport, not scientific acceptance.', '- **Reviewed scope:** the primitive-positive-weight defect-at-most-four theorem is `reviewed_scoped` at candidate `96fc7ec34bd3b685a0edeae7ecd4404abab7e2f1`; the fixed primitive-positive-weight, actual-defect-five theorem is separately `reviewed_scoped` as `CLM-073` at candidate `2eeb36d232366d124b5a66774b29769ec1eba43d`.', '- **Review binding:** each filtered theorem has its own independent `ACCEPT` and freeze record; neither review produces a qualifying weight for arbitrary Keller pairs.', '- **Explicit nonclaims:** no theorem producing a qualifying weight for every Keller pair, no defect-six or arbitrary-termination theorem, and no proof of `JC_2`.', '', '## Machine-derived inventory', '', f"- Claims: **{len(claims['claims'])}** across **{len(claim_counts)}** statuses.", f"- Reviewed-scoped claims: **{claim_counts.get('reviewed_scoped', 0)}**.", f"- Proof graph: **{len(graph['nodes'])}** nodes and **{len(graph['edges'])}** directed edges.", '- Graph node statuses: ' + ', '.join((f'{code(k)} {v}' for k, v in sorted(node_counts.items()))) + '.', f"- Open canonical leaves: **{len(queue['leaves'])}**; recorded dispositions: **{len(queue.get('dispositions', []))}**.", f'- Metadata-only conversation exports: **{len(metadata_exports)}**; completion remains issue [#22](https://github.com/snissn/planar-jacobian/issues/22).', '', '## Integrated scientific packets', '', '- **Issue #3:** `CLM-074` excludes planar Keller function-field degree three at `literature_bound` scope through Orevkov\'s audited primary theorem. `L14` and `CLM-059` are disposed only at rank-three scope without a constructed unit-index section. Conditional refinements `CLM-075`–`CLM-078` remain `candidate_proved`; no degree-four-or-higher or `JC_2` result follows.', '- **Issue #4:** the source-reflexive-lattice successor proves at mutable candidate scope that a finite full pair-stable module yields a finite locally free stable multiplier order and that divisorial source-pole stages escape at ramification. No finite pair-stable lattice is constructed; issue #4 remains open.', '- **Issue #5:** the one-boundary successor excludes torus-invariant generically ramified and purely unramified one-boundary subclasses at mutable candidate scope. The general non-toric Laurent/conductor system remains open as `CLM-072`; exactness still permits higher principal parts.', '- **Issue #17:** the exact positive-weight defect-at-most-four theorem is reviewed only at the pinned revision. It creates no terminal edge to `JC_2`.', '- **Issues #29 and #38:** fixed primitive positive weight and actual defect five is `CLM-073` at `reviewed_scoped` status, bound to independent `ACCEPT` at candidate `2eeb36d232366d124b5a66774b29769ec1eba43d`. No qualifying-weight, arbitrary-termination, generic defect-six, or `JC_2` claim is introduced.', '', '## P0 resume order', '']
    for leaf in p0:
        rel = os.path.relpath(ROOT / leaf['artifact'], start=ROOT).replace(os.sep, '/')
        lines.append(f"- {code(leaf['id'])}: [{leaf['title']}]({rel}) — issue [#{leaf['issue_number']}](https://github.com/snissn/planar-jacobian/issues/{leaf['issue_number']}).")
    lines += ['', 'Issue [#2](https://github.com/snissn/planar-jacobian/issues/2) is the durable coordination surface. Start from latest `main`, reserve an issue-specific path, and update shared ledgers only during final synchronization.', '', 'Run `python3 scripts/frontier.py` for the full generated frontier. Structural and symbolic validators are engineering evidence and do not evaluate mathematical truth.', '', '## Provenance warning', '', 'Unavailable complete conversation exports were not reconstructed or fabricated. Their declared identities remain `metadata_only`; exact-byte manifests are optional provenance unless a claim-specific review requires them.', '']
    return '\n'.join(lines)

def expected_outputs() -> dict[str, str]:
    claims = load_json('research/claim_ledger.json')
    graph = load_json('research/proof_graph.json')
    queue = load_json('research/work_queue.json')
    legacy = load_json('research/legacy_claim_ledger.json')
    manifest = load_json('archive/manifest.json')
    return {'research/CLAIM_LEDGER.md': render_claim_ledger(claims), 'research/PROOF_GRAPH.md': render_proof_graph(graph), 'research/WORK_QUEUE.md': render_work_queue(queue), 'research/ISSUE_INDEX.md': render_issue_index(queue), 'research/LEGACY_CLAIM_MIGRATION.md': render_legacy_migration(legacy), 'STATUS.md': render_status(claims, graph, queue, manifest)}

def main() -> int:
    parser = argparse.ArgumentParser()
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument('--write', action='store_true', help='write generated Markdown views')
    mode.add_argument('--check', action='store_true', help='verify generated Markdown views are current')
    args = parser.parse_args()
    outputs = expected_outputs()
    stale: list[str] = []
    for relative_path, expected in outputs.items():
        path = ROOT / relative_path
        expected_bytes = (expected.rstrip() + '\n').encode('utf-8')
        if args.write:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(expected_bytes)
            print(f'wrote {relative_path}')
        else:
            actual = path.read_bytes() if path.exists() else b''
            if actual != expected_bytes:
                stale.append(relative_path)
    if stale:
        for path in stale:
            print(f'STALE: {path}')
        print('Run: python3 scripts/render_views.py --write')
        return 1
    if args.check:
        print(f'generated views: PASS ({len(outputs)} files)')
    return 0
if __name__ == '__main__':
    raise SystemExit(main())
